function initFaqAccordion(){const t=document.getElementsByClassName("faq-btn");for(let e=0;e<t.length;e++)t[e].addEventListener("click",function(){this.classList.toggle("active");const t=this.nextElementSibling;t.style.maxHeight?t.style.maxHeight=null:t.style.maxHeight=t.scrollHeight+"px"})}function initShareButton(){const t=document.getElementById("share-btn");t&&t.addEventListener("click",()=>{navigator.share?navigator.share({title:document.title,text:"Explore the Bharat Award - the highest honour for exceptional bravery by children.",url:window.location.href}).catch(t=>console.log("Error sharing",t)):navigator.clipboard.writeText(window.location.href).then(()=>{alert("Link copied to clipboard!")})})}document.addEventListener("DOMContentLoaded",()=>{initFaqAccordion(),initShareButton()});